-- Generated by scripts/build-app-events.py; do not edit by hand.
-- Run it from the folder that holds the CSV files (datasets/app-events/v1/). To load from the web instead, replace
-- each file name with the release-tag URL of that file (see README.md).

CREATE OR REPLACE TABLE users (
  user_id INTEGER,
  signup_date DATE,
  channel VARCHAR,
  region VARCHAR,
  plan_at_signup VARCHAR
);
COPY users FROM 'users.csv' (HEADER, DELIMITER ',');

CREATE OR REPLACE TABLE events (
  event_id INTEGER,
  user_id INTEGER,
  event_ts TIMESTAMP,
  event_name VARCHAR,
  platform VARCHAR,
  received_at TIMESTAMP
);
COPY events FROM 'events.csv' (HEADER, DELIMITER ',');

CREATE OR REPLACE TABLE subscriptions (
  subscription_id INTEGER,
  user_id INTEGER,
  plan VARCHAR,
  started_on DATE,
  ended_on DATE,
  updated_at TIMESTAMP,
  cancel_reason VARCHAR
);
COPY subscriptions FROM 'subscriptions.csv' (HEADER, DELIMITER ',');

CREATE OR REPLACE TABLE experiment_assignments (
  user_id INTEGER,
  experiment VARCHAR,
  variant VARCHAR,
  assigned_at TIMESTAMP,
  converted BOOLEAN
);
COPY experiment_assignments FROM 'experiment_assignments.csv' (HEADER, DELIMITER ',');
